'use strict';

// MODULES //

var resolve = require( 'path' ).resolve;
var browserify = require( 'browserify' );
var packFlat = require( 'browser-pack-flat/plugin' ); // eslint-disable-line stdlib/require-file-extensions
var uglify = require( 'uglify-js' );
var writeFile = require( '@stdlib/fs/write-file' ).sync;
var join = require( '@stdlib/array/base/join' );


// VARIABLES //

var fpath = resolve( __dirname, '..', 'lib', 'browser', 'app', 'index.js' );
var opath = resolve( __dirname, '..', 'lib', 'browser', 'routes', 'app', 'bundle.js' );
var fopts = {
	'encoding': 'utf8'
};
var PREAMBLE = [
	'/* @license Apache-2.0 */',
	'',
	'/* eslint-disable */',
	'',
	'/* editorconfig-checker-disable-file */',
	''
];
var MINIFY = true;


// MAIN //

/**
* Main execution sequence.
*
* @private
*/
function main() {
	var opts;
	var b;

	opts = {
		'plugin': [ packFlat ]
	};
	b = browserify( [ fpath ], opts );
	b.bundle( onBundle );

	/**
	* Callback invoked upon creating a bundle.
	*
	* @private
	* @param {(Error|null)} error - error object
	* @param {Buffer} bundle - bundle
	* @throws {Error} unexpected error
	*/
	function onBundle( error, bundle ) {
		if ( error ) {
			throw error;
		}
		if ( MINIFY ) {
			bundle = uglify.minify( bundle.toString() ).code;
		} else {
			bundle = bundle.toString();
		}
		error = writeFile( opath, join( PREAMBLE, '\n' )+bundle+'\n', fopts );
		if ( error ) {
			throw error;
		}
		console.log( 'Successfully created bundle.' );
	}
}

main();
